INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','present-perfect','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"present-perfect","title":"Present perfect: experience and results","level":"B1","order":29,"summary":"The present perfect connects earlier events with the present: an experience so far, a recent result or a period that is still open. Contrast this with a finished past time such as yesterday. A past participle may resemble the past simple, but irregular verbs can differ: went / gone, saw / seen.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Connect two points in time","Build the perfect verb","Negatives and questions","Time expressions and short answers"],"rules":[{"title":"Connect two points in time","explanation":"The present perfect connects earlier events with the present: an experience so far, a recent result or a period that is still open. Contrast this with a finished past time such as yesterday. A past participle may resemble the past simple, but irregular verbs can differ: went / gone, saw / seen.","pattern":"Subject + **have / has + past participle**","commonMistakes":["For a finished date, use past simple: I visited last year. British English often prefers present perfect with just or already; American English also uses past simple in those contexts."],"examples":["Use the present perfect: She **has prepared** the visitor guide up to now.","Use the present perfect: She **has restored** the old portrait up to now."],"skill":"form"},{"title":"Build the perfect verb","explanation":"A perfect construction uses **have as an auxiliary**, followed by a past participle. Regular participles normally end in -ed. Irregular ones must be learned with their base and past forms: write / wrote / written. Do not substitute an -ing form unless you also build the continuous construction.","pattern":"She **has written**. / They **have written**.","commonMistakes":["The form written is a participle; wrote is past simple. They are not interchangeable after have."],"examples":["Make a present-perfect negative: They **have not prepared** the visitor guide up to now.","Make a present-perfect negative: They **have not restored** the old portrait up to now."],"skill":"meaning"},{"title":"Negatives and questions","explanation":"Put **not after have or has**. For a yes/no question, move the auxiliary before the subject. The participle stays unchanged. There is no extra do or did because the perfect construction already contains an auxiliary.","pattern":"Have they finished? / They **have not finished**.","commonMistakes":["Do not combine did with a perfect auxiliary to make its negative or question."],"examples":["Begin this present-perfect question: **Have** they prepared the visitor guide up to now?","Begin this present-perfect question: **Have** they restored the old portrait up to now?"],"skill":"contrast"},{"title":"Time expressions and short answers","explanation":"Read the whole sentence to locate the reference time. Here it is **up to now**. Keep the appropriate form of have in a short answer and omit the repeated participle. Since names a starting point; for names a duration. Neither word automatically selects a single tense.","pattern":"Yes, they **have**. / No, they **have not**.","commonMistakes":["Been can describe a completed visit; gone often means the person has left and has not yet returned."],"examples":["Choose the participle for the present perfect: We have **prepared** the visitor guide up to now. (prepare)","Choose the participle for the present perfect: We have **restored** the old portrait up to now. (restore)"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["The present perfect connects earlier events with the present: an experience so far, a recent result or a period that is still open. Contrast this with a finished past time such as yesterday. A past participle may resemble the past simple, but irregular verbs can differ: went / gone, saw / seen.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Connect two points in time","explanation":"The present perfect connects earlier events with the present: an experience so far, a recent result or a period that is still open. Contrast this with a finished past time such as yesterday. A past participle may resemble the past simple, but irregular verbs can differ: went / gone, saw / seen.","pattern":"Subject + **have / has + past participle**","commonMistakes":["For a finished date, use past simple: I visited last year. British English often prefers present perfect with just or already; American English also uses past simple in those contexts."],"examples":["Use the present perfect: She **has prepared** the visitor guide up to now.","Use the present perfect: She **has restored** the old portrait up to now."],"skill":"form","id":"present-perfect-foundation-1","domain":"verbs","referenceIds":["bc-present-perfect"],"readingVersion":"core-2026-09-v3"},{"title":"Build the perfect verb","explanation":"A perfect construction uses **have as an auxiliary**, followed by a past participle. Regular participles normally end in -ed. Irregular ones must be learned with their base and past forms: write / wrote / written. Do not substitute an -ing form unless you also build the continuous construction.","pattern":"She **has written**. / They **have written**.","commonMistakes":["The form written is a participle; wrote is past simple. They are not interchangeable after have."],"examples":["Make a present-perfect negative: They **have not prepared** the visitor guide up to now.","Make a present-perfect negative: They **have not restored** the old portrait up to now."],"skill":"meaning","id":"present-perfect-foundation-2","domain":"verbs","referenceIds":["bc-present-perfect"],"readingVersion":"core-2026-09-v3"},{"title":"Negatives and questions","explanation":"Put **not after have or has**. For a yes/no question, move the auxiliary before the subject. The participle stays unchanged. There is no extra do or did because the perfect construction already contains an auxiliary.","pattern":"Have they finished? / They **have not finished**.","commonMistakes":["Do not combine did with a perfect auxiliary to make its negative or question."],"examples":["Begin this present-perfect question: **Have** they prepared the visitor guide up to now?","Begin this present-perfect question: **Have** they restored the old portrait up to now?"],"skill":"contrast","id":"present-perfect-foundation-3","domain":"verbs","referenceIds":["bc-present-perfect"],"readingVersion":"core-2026-09-v3"},{"title":"Time expressions and short answers","explanation":"Read the whole sentence to locate the reference time. Here it is **up to now**. Keep the appropriate form of have in a short answer and omit the repeated participle. Since names a starting point; for names a duration. Neither word automatically selects a single tense.","pattern":"Yes, they **have**. / No, they **have not**.","commonMistakes":["Been can describe a completed visit; gone often means the person has left and has not yet returned."],"examples":["Choose the participle for the present perfect: We have **prepared** the visitor guide up to now. (prepare)","Choose the participle for the present perfect: We have **restored** the old portrait up to now. (restore)"],"skill":"application","id":"present-perfect-foundation-4","domain":"verbs","referenceIds":["bc-present-perfect"],"readingVersion":"core-2026-09-v3"},{"domain":"verbs","id":"perfect-versus-past","title":"Present perfect versus a finished past","explanation":"Use present perfect when an earlier situation is connected to a present reference frame, such as experience so far, an unfinished period or a current result. Past simple places it in a finished past frame. Speakers can choose a frame rather than simply obey a keyword. British and American usage differs with some recent-event expressions.","pattern":"I **have seen** it. / I **saw** it yesterday.","examples":["I **have had** two coffees today, and the day is not over.","When I lived there, I **visited** the museum twice."],"commonMistakes":["A present consequence does not forbid past simple: I lost my key yesterday is correct even if it is still missing. The explicit finished time selects the past frame."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"verbs","id":"perfect-adverbs-duration","title":"For, since, ever, never, just, already, yet and still","explanation":"For measures a duration; since gives its starting point. Ever and never relate an event to a period of possible experience. Just, already, yet and still locate it relative to expectation or continuation. Their positions and tense preferences depend on meaning and variety. They are clues, not automatic tense selectors.","pattern":"**for three years** / **since 2022**","examples":["She has **already left**, but he has **not left yet**.","I lived there **for three years** before moving away."],"commonMistakes":["Since can also mean because, and for can express a purpose or recipient. Identify the word’s function before using it to reason about tense."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"verbs","id":"been-gone-and-continuing-states","title":"Been, gone, finished events and continuing states","explanation":"Have been to commonly presents a visit as completed, while have gone to commonly indicates departure with the person still away. Perfect simple with a state can describe something continuing now. A negative perfect can also measure a period with no occurrence. Interpret the reference time and lexical meaning together.","pattern":"She has **been to** Rome. / She has **gone to** Rome.","examples":["I have **known** him for years.","We **haven’t heard** from her since Monday."],"commonMistakes":["Have been in a place for a duration may mean the person is still there. The completed-visit reading of been to should not be imposed on every construction with been."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["Subject + **have / has + past participle**","She **has written**. / They **have written**.","Have they finished? / They **have not finished**.","Yes, they **have**. / No, they **have not**."],"readingVersion":"core-2026-09-v4"},"stage":"3 · Time and experience","prerequisites":["future-forms"],"readingReferenceIds":["bc-present-perfect","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='present-perfect'
